DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THE11CATS' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THE11CATS_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_TEXT_1','The 11 Cats[NEWLINE]Peaceful city specialization through a persistent household[NEWLINE]Culture; Science or Diplomacy through healthy specialized cities[NEWLINE][NEWLINE]Place companions in cities where their resident effects and compatible bonds support a coherent economy. The household is a long-term allocation system; the final family count is a narrative milestone, not an extra yield package.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_TEXT_2','Establish safe food, Culture and expansion for future homes. When a companion arrives, inspect its actual resident effects and settle it into a useful available home instead of leaving it travelling unnecessarily.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_TEXT_3','Use the Homes and Bonds views to plan small groups within the resident limit. Combine complementary effects with real local infrastructure. Rehome deliberately when conditions change, respecting recovery, arrival and action restrictions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_TEXT_4','Convert mature homes and longer genuine WLTKD celebrations into the infrastructure needed for a normal cultural or diplomatic victory. Keep travelers protected and maintain safe arrivals when a companion is recovering.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_TEXT_5','- Several distinct resident effects allow meaningful city specialization.[NEWLINE]- Family Bonds reward deliberate household composition.[NEWLINE]- Longer genuine WLTKD celebrations support a peaceful growth plan.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_TEXT_6','- Each city has limited resident capacity.[NEWLINE]- Companions arrive through Era chapters rather than all at the start.[NEWLINE]- The household does not supply a general early military breakthrough.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_TEXT_7','- Pressure promising homes and the routes used by travelling companions.[NEWLINE]- Force emergency military investment before peaceful specialization has matured.[NEWLINE]- Contest the ordinary cultural and diplomatic objectives rather than expecting the family milestone itself to win the game.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_TEXT_8','- Assuming Austin is an ordinary movable cat unit.[NEWLINE]- Expecting eleven residents in one city or unlimited bond stacking.[NEWLINE]- Treating Everyone Is Home as an extra yield reward or a standard victory.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Saba: City specialization can exploit strong non-Desert sites while Saba''s signature city-centre bonuses remain geography-dependent.[NEWLINE][NEWLINE]The Wandering Circus: Settled resident benefits do not require a recurring Crew trip through each home, helping in a difficult travel network.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Fast early settlement can take useful home sites before the household fully develops.[NEWLINE][NEWLINE]The Filthy Realm: Disruption of a carefully specialized home can reduce several complementary benefits at once.');
