INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_BACKGROUND','Place companions in cities where their resident effects and compatible bonds support a coherent economy. The household is a long-term allocation system; the final family count is a narrative milestone, not an extra yield package.');
