INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_STRATEGY','Place companions in cities where their resident effects and compatible bonds support a coherent economy. The household is a long-term allocation system; the final family count is a narrative milestone, not an extra yield package.[NEWLINE][NEWLINE]Establish safe food, Culture and expansion for future homes. When a companion arrives, inspect its actual resident effects and settle it into a useful available home instead of leaving it travelling unnecessarily.[NEWLINE][NEWLINE]Use the Homes and Bonds views to plan small groups within the resident limit. Combine complementary effects with real local infrastructure. Rehome deliberately when conditions change, respecting recovery, arrival and action restrictions.[NEWLINE][NEWLINE]Convert mature homes and longer genuine WLTKD celebrations into the infrastructure needed for a normal cultural or diplomatic victory. Keep travelers protected and maintain safe arrivals when a companion is recovering.');
