INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_LEADER_TEXT_1','The 11 Cats[NEWLINE]Peaceful city specialization through a persistent household[NEWLINE]Culture; Science or Diplomacy through healthy specialized cities[NEWLINE][NEWLINE]Place companions in cities where their resident effects and compatible bonds support a coherent economy. The household is a long-term allocation system; the final family count is a narrative milestone, not an extra yield package.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_LEADER_TEXT_2','Establish safe food, Culture and expansion for future homes. When a companion arrives, inspect its actual resident effects and settle it into a useful available home instead of leaving it travelling unnecessarily.[NEWLINE][NEWLINE]Use the Homes and Bonds views to plan small groups within the resident limit. Combine complementary effects with real local infrastructure. Rehome deliberately when conditions change, respecting recovery, arrival and action restrictions.[NEWLINE][NEWLINE]Convert mature homes and longer genuine WLTKD celebrations into the infrastructure needed for a normal cultural or diplomatic victory. Keep travelers protected and maintain safe arrivals when a companion is recovering.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THE11CATS_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Saba: City specialization can exploit strong non-Desert sites while Saba''s signature city-centre bonuses remain geography-dependent.[NEWLINE][NEWLINE]The Wandering Circus: Settled resident benefits do not require a recurring Crew trip through each home, helping in a difficult travel network.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Fast early settlement can take useful home sites before the household fully develops.[NEWLINE][NEWLINE]The Filthy Realm: Disruption of a carefully specialized home can reduce several complementary benefits at once.');
